import React, { useState } from 'react';
import { Dialog } from 'primereact/dialog';
import { Button } from 'primereact/button';

export default function Position() {
    const [visible, setVisible] = useState(false);
    const [position, setPosition] = useState('center');
    const footerContent = (
        <>
            <Button label="No" icon="pi pi-times" onClick={() => setVisible(false)} className="p-button-text" />
            <Button label="Yes" icon="pi pi-check" onClick={() => setVisible(false)} autoFocus />
        </>
    );

    const show = (position) => {
        setPosition(position);
        setVisible(true);
    };

    return (
        <div className="fxb fvc  wrap gp5">
            <div className="fxb fvc gp5">
                <Button label="Left" icon="pi pi-arrow-right" onClick={() => show('left')} severity="help" size="small" />
                <Button label="Right" icon="pi pi-arrow-left" onClick={() => show('right')} severity="help" size="small" />
            </div>
            <div className="fxb fvc gp5">
                <Button label="TopLeft" icon="pi pi-arrow-down-right" onClick={() => show('top-left')} severity="warning" size="small" />
                <Button label="Top" icon="pi pi-arrow-down" onClick={() => show('top')} severity="warning" size="small" />
                <Button label="TopRight" icon="pi pi-arrow-down-left" onClick={() => show('top-right')} severity="warning" size="small" />
            </div>
            <div className="fxb fvc gp5">
                <Button label="BottomLeft" icon="pi pi-arrow-up-right" onClick={() => show('bottom-left')} severity="success" size="small" />
                <Button label="Bottom" icon="pi pi-arrow-up" onClick={() => show('bottom')} severity="success" size="small" />
                <Button label="BottomRight" icon="pi pi-arrow-up-left" onClick={() => show('bottom-right')} severity="success" size="small" />
            </div>

            <Dialog header="Header" visible={visible} position={position} style={{ width: '50vw' }} onHide={() => {if (!visible) return; setVisible(false); }} footer={footerContent} draggable={false} resizable={false}>
                <p className="m-0">
                    Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. 
                    Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo
                    consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. 
                    Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.
                </p>
            </Dialog>
        </div>
    )

}